	private static Seed seedStore(Path storeDir, LmdbStoreConfig config, int count) throws Exception {
		Seed first = null;
		LmdbStore store = new LmdbStore(storeDir.toFile(), config);
		store.init();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			for (int i = 0; i < count; i++) {
				IRI innerSubject = VF.createIRI("urn:value-term-index:inner-subject:" + i);
				IRI outerSubject = VF.createIRI("urn:value-term-index:outer-subject:" + i);
				IRI carrier = VF.createIRI("urn:value-term-index:carrier:" + i);
				TripleTerm inner = VF.createTripleTerm(innerSubject, PREDICATE, VF.createLiteral("nested-leaf:" + i));
				TripleTerm outer = VF.createTripleTerm(outerSubject, PREDICATE, inner);
				connection.addStatement(carrier, PREDICATE, outer, GRAPH);
				if (i == 0) {
					first = new Seed(carrier, outer, inner);
				}
			}
			connection.commit();
		} finally {
			store.shutDown();
		}
		return first;
	}

	private static void assertStatementAndSelectiveTermQuery(LmdbStore store, Seed seed) throws Exception {
		try (SailConnection connection = store.getConnection()) {
			try (CloseableIteration<? extends Statement> statements = connection.getStatements(seed.carrier(),
					PREDICATE,
					seed.outer(), false, GRAPH)) {
				assertTrue(statements.hasNext(),
						"the public statement access path must resolve the nested quoted object");
				Statement statement = statements.next();
				assertEquals(seed.outer(), statement.getObject());
				assertEquals(GRAPH, statement.getContext(), "the public statement access path must preserve its graph");
				assertFalse(statements.hasNext());
			}
		}

		try (SailDataset dataset = store.getBackingStore()
				.getExplicitSailSource()
				.dataset(IsolationLevels.SNAPSHOT_READ);
				CloseableIteration<? extends TripleTerm> terms = dataset.getTriples(null, null, seed.inner())) {
			assertTrue(terms.hasNext(), "the object-bound triple-term path must find its enclosing quoted triple");
			assertEquals(seed.outer(), terms.next());
			assertFalse(terms.hasNext());
		}
	}

	private static void assertAllBoundNestedTermLookup(LmdbStore store, Seed seed, String expectedIndex)
			throws Exception {
		ValueStore valueStore = (ValueStore) store.getValueFactory();
		long subject = valueStore.getId(seed.outer().getSubject());
		long predicate = valueStore.getId(seed.outer().getPredicate());
		long object = valueStore.getId(seed.outer().getObject());
		try (RecordIterator terms = valueStore.getTripleTerms(subject, predicate, object)) {
			assertEquals(expectedIndex, terms.getIndexName(), "the exact query must exercise the rebuilt index");
			long[] record = terms.next();
			assertNotNull(record, "the all-bound query must find the nested quoted triple");
			assertEquals(subject, record[TripleIndex.SUBJ_IDX]);
			assertEquals(predicate, record[TripleIndex.PRED_IDX]);
			assertEquals(object, record[TripleIndex.OBJ_IDX]);
			assertNull(terms.next(), "the all-bound query must return only the exact nested quoted triple");
		}
	}

	private static long[] exactOpscKey(LmdbStore store, Seed seed) throws IOException {
		ValueStore valueStore = (ValueStore) store.getValueFactory();
		return new long[] {
				valueStore.getId(seed.outer().getObject()),
				valueStore.getId(seed.outer().getPredicate()),
				valueStore.getId(seed.outer().getSubject()),
				valueStore.getId(seed.outer())
		};
	}

	private static void assertExactTermIndexKey(Path environmentDirectory, String indexSpec, long[] keyValues)
			throws IOException {
		long environment = NULL;
		long transaction = NULL;
		long cursor = NULL;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			environment = pointer.get(0);
			E(mdb_env_set_maxdbs(environment, 32));
			E(mdb_env_open(environment, environmentDirectory.toAbsolutePath().toString(), MDB_NOTLS | MDB_RDONLY,
					0664));
			E(mdb_txn_begin(environment, NULL, MDB_RDONLY, pointer));
			transaction = pointer.get(0);

			IntBuffer dbi = stack.mallocInt(1);
			String databaseName = termIndexDatabaseName(indexSpec);
			assertEquals(MDB_SUCCESS, mdb_dbi_open(transaction, stack.UTF8(databaseName), 0, dbi),
					"the expected rebuilt term-index DBI must exist: " + databaseName);
			E(mdb_cursor_open(transaction, dbi.get(0), pointer));
			cursor = pointer.get(0);

			ByteBuffer keyBytes = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
			for (long value : keyValues) {
				Varint.writeUnsigned(keyBytes, value);
			}
			keyBytes.flip();
			MDBVal key = MDBVal.calloc(stack);
			key.mv_size(keyBytes.remaining());
			key.mv_data(keyBytes);
			MDBVal value = MDBVal.calloc(stack);
			assertEquals(MDB_SUCCESS, mdb_cursor_get(cursor, key, value, MDB_SET),
					"the reindexed " + indexSpec + " key must retain its exact variable-length encoding");
		} finally {
			if (cursor != NULL) {
				mdb_cursor_close(cursor);
			}
			if (transaction != NULL) {
				mdb_txn_abort(transaction);
			}
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	private static void assertCommittedOptionalTermIndex(LmdbStore store, Seed first, int fixtureSize)
			throws Exception {
		Map<String, LmdbStore.LmdbDatabaseStats> valueDatabases = store.getLmdbStats().valueDatabases();
		String databaseName = termIndexDatabaseName("opsc");
		assertTrue(valueDatabases.containsKey(databaseName),
				"the native term-index manifest must recover the committed optional index");
		assertEquals(fixtureSize * 2, valueDatabases.get(databaseName).entries(),
				"both levels of each nested quote must be indexed");
		assertStatementAndSelectiveTermQuery(store, first);
	}

	private static LmdbStoreConfig legacyConfig() {
		return new LmdbStoreConfig("spoc").setForceSync(true);
	}

	private static LmdbStoreConfig smallMapConfig() {
		return new LmdbStoreConfig("spoc").setForceSync(true).setValueDBSize(128L * 4096);
	}

	private static String termIndexDatabaseName(String fieldSequence) {
		String name = "term-" + fieldSequence;
		return name + name;
	}

	private static Process startTermIndexCrashChild(Path storeDir, String addedIndex, long valueMapSize)
			throws IOException {
		return startChild(TermIndexCrashChildMain.class, storeDir, addedIndex, valueMapSize);
	}

	private static Process startTermIndexRebuildChild(Path storeDir, String indexSpecs, long valueMapSize)
			throws IOException {
		return startChild(TermIndexRebuildChildMain.class, storeDir, indexSpecs, valueMapSize);
	}

	private static Process startChild(Class<?> childMain, Path storeDir, String indexSpecs, long valueMapSize)
			throws IOException {
		String javaBinary = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		return new ProcessBuilder(javaBinary, "-cp", System.getProperty("java.class.path"), childMain.getName(),
				storeDir.toAbsolutePath().toString(), indexSpecs, Long.toString(valueMapSize))
						.redirectErrorStream(true)
						.start();
	}

	private static String awaitProcess(Process child, long timeout, TimeUnit unit) throws Exception {
		if (!child.waitFor(timeout, unit)) {
			child.destroyForcibly();
			assertTrue(child.waitFor(10, TimeUnit.SECONDS), "the isolated child must terminate after the timeout");
			throw new AssertionError("the isolated term-index child did not finish within " + timeout + " " + unit);
		}
		return new String(child.getInputStream().readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
	}

	private static long valueMapSize(Path environmentDirectory) throws IOException {
		long environment = NULL;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			environment = pointer.get(0);
			E(mdb_env_open(environment, environmentDirectory.toAbsolutePath().toString(), MDB_NOTLS | MDB_RDONLY,
					0664));
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(environment, info));
			return info.me_mapsize();
		} finally {
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	private static void createOrphanTermIndexDatabases(Path environmentDirectory, String... indexSpecs)
			throws IOException {
		long environment = NULL;
		long transaction = NULL;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			environment = pointer.get(0);
			E(mdb_env_set_maxdbs(environment, 32));
			E(mdb_env_open(environment, environmentDirectory.toAbsolutePath().toString(), MDB_NOTLS, 0664));
			E(mdb_txn_begin(environment, NULL, 0, pointer));
			transaction = pointer.get(0);

			IntBuffer dbi = stack.mallocInt(1);
			for (String indexSpec : indexSpecs) {
				String databaseName = termIndexDatabaseName(indexSpec);
				E(mdb_dbi_open(transaction, stack.UTF8(databaseName), MDB_CREATE, dbi));
			}
			E(mdb_txn_commit(transaction));
			transaction = NULL;
		} finally {
			if (transaction != NULL) {
				mdb_txn_abort(transaction);
			}
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	private static void removeTermIndexManifest(Path environmentDirectory) throws IOException {
		long environment = NULL;
		long transaction = NULL;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			environment = pointer.get(0);
			E(mdb_env_set_maxdbs(environment, 32));
			E(mdb_env_open(environment, environmentDirectory.toAbsolutePath().toString(), MDB_NOTLS, 0664));
			E(mdb_txn_begin(environment, NULL, 0, pointer));
			transaction = pointer.get(0);

			IntBuffer dbi = stack.mallocInt(1);
			int openResult = mdb_dbi_open(transaction, stack.UTF8("term_index_manifest"), 0, dbi);
			if (openResult == MDB_NOTFOUND) {
				E(mdb_dbi_open(transaction, stack.UTF8("term_index_manifest"), MDB_CREATE, dbi));
			} else {
				E(openResult);
			}
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(stack.bytes("term-index-specs".getBytes(StandardCharsets.US_ASCII)));
			int deleteResult = mdb_del(transaction, dbi.get(0), key, null);
			if (deleteResult != MDB_NOTFOUND) {
				E(deleteResult);
			}
			E(mdb_txn_commit(transaction));
			transaction = NULL;
		} finally {
			if (transaction != NULL) {
				mdb_txn_abort(transaction);
			}
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	public static final class TermIndexCrashChildMain {

		public static void main(String[] args) {
			Path storeDir = Path.of(args[0]);
			String indexSpecs = args[1];
			LmdbStoreConfig config = new LmdbStoreConfig("spoc").setTripleTermIndexes(indexSpecs)
					.setValueDBSize(Long.parseLong(args[2]))
					.setForceSync(true);
			LmdbStore store = new LmdbStore(storeDir.toFile(), config) {
				@Override
				LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig storeConfig,
						boolean sketchBasedJoinEstimatorEnabled) throws IOException, SailException {
					LmdbSailStore backingStore = super.createBackingStore(dataDir, properties, storeConfig,
							sketchBasedJoinEstimatorEnabled);
					Map<String, LmdbStore.LmdbDatabaseStats> valueDatabases = backingStore.getLmdbStats()
							.valueDatabases();
					if (!valueDatabases.containsKey(termIndexDatabaseName("opsc"))) {
						throw new AssertionError(
								"The requested native term index was not created: " + valueDatabases.keySet());
					}
					System.out.println("VALUE_TERM_INDEX_NATIVE_COMMITTED");
					try {
						String text = Files.readString(new File(dataDir, StoreProperties.FILE_NAME).toPath());
						System.out.println(text.contains("opsc") ? "VALUE_TERM_INDEX_PROPERTIES_ALREADY_UPDATED"
								: "VALUE_TERM_INDEX_OLD_PROPERTIES_STILL_ON_DISK");
					} catch (IOException e) {
						throw new RuntimeException(e);
					}
					System.out.flush();
					Runtime.getRuntime().halt(86);
					return backingStore;
				}
			};
			store.init();
			throw new AssertionError("The term-index crash cut point was not reached");
		}
	}

