	public static final class PostCommitFailureChildMain {

		public static void main(String[] args) throws Exception {
			File valueDirectory = Path.of(args[0]).resolve("values").toFile();
			LmdbStoreConfig config = new LmdbStoreConfig().setForceSync(true);
			PostCommitFailureValueStore store = new PostCommitFailureValueStore(valueDirectory, config);
			store.startTransaction(true);
			long id = store.storeValue(VF.createLiteral("committed-before-callback-failure"));
			store.failAfterNextNativeCommit();
			try {
				store.commit();
				throw new AssertionError("the test commit hook must fail after native commit");
			} catch (IllegalStateException expected) {
				if (!"injected failure after native commit".equals(expected.getMessage())) {
					throw expected;
				}
			}
			store.close();

			ValueStore reopened = new ValueStore(valueDirectory, config);
			try {
				if (!VF.createLiteral("committed-before-callback-failure").equals(reopened.getValue(id))) {
					throw new AssertionError("the native-committed value must survive recovery");
				}
			} finally {
				reopened.close();
			}
			System.out.println("VALUE_TXN_POSTCOMMIT_RECOVERED");
		}
	}

	public static final class DropMapFullRetryChildMain {

		public static void main(String[] args) throws Exception {
			File valueDirectory = Path.of(args[0]).resolve("values").toFile();
			LmdbStoreConfig config = new LmdbStoreConfig().setTripleTermIndexes(args[1]).setForceSync(true);
			DropMapFullValueStore.injectMapFullAfterNextSuccessfulDrop = true;
			ValueStore replacement = new DropMapFullValueStore(valueDirectory, config);
			if (DropMapFullValueStore.injectMapFullAfterNextSuccessfulDrop) {
				throw new AssertionError("the test must force one retry after the native drop closes its DBI");
			}
			replacement.close();

			ValueStore reopened = new ValueStore(valueDirectory, config);
			reopened.close();
			System.out.println("VALUE_TERM_INDEX_DROP_RETRY_COMPLETE");
		}
	}

	private static final class PostCommitFailureValueStore extends ValueStore {

		private boolean failAfterNextNativeCommit;

		private PostCommitFailureValueStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config);
		}

		void failAfterNextNativeCommit() {
			failAfterNextNativeCommit = true;
		}

		@Override
		int commitWriteTransaction(long transaction) {
			int rc = super.commitWriteTransaction(transaction);
			if (failAfterNextNativeCommit && rc == MDB_SUCCESS) {
				failAfterNextNativeCommit = false;
				throw new IllegalStateException("injected failure after native commit");
			}
			return rc;
		}
	}

	private static final class FailingInitializationValueStore extends ValueStore {

		private static final AtomicInteger environmentCloseCount = new AtomicInteger();

		private FailingInitializationValueStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config);
		}

		@Override
		void initTermIndexes(LmdbStoreConfig config) throws IOException {
			throw new IOException("injected term-index initialization failure");
		}

		@Override
		void closeEnvironment(long environment) {
			environmentCloseCount.incrementAndGet();
			super.closeEnvironment(environment);
		}
	}

	private static final class RollbackCallbackFailureValueStore extends ValueStore {

		private int nativeAbortCount;
		private boolean failAfterRollbackCleanup;

		private RollbackCallbackFailureValueStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config);
		}

		void failAfterRollbackCleanup() {
			failAfterRollbackCleanup = true;
		}

		@Override
		void rollbackRetiredIds() {
			super.rollbackRetiredIds();
			if (failAfterRollbackCleanup) {
				failAfterRollbackCleanup = false;
				throw new IllegalStateException("injected rollback cleanup failure");
			}
		}

		@Override
		void abortWriteTransaction(long transaction) {
			nativeAbortCount++;
			if (nativeAbortCount == 1) {
				super.abortWriteTransaction(transaction);
			}
		}
	}

	private static final class FinalManifestCommitMapFullValueStore extends ValueStore {

		private static final AtomicBoolean failAfterDrop = new AtomicBoolean();
		private static final AtomicBoolean sawSuccessfulDrop = new AtomicBoolean();
		private static final AtomicBoolean injectedMapFull = new AtomicBoolean();
		private static final AtomicInteger environmentCloseCount = new AtomicInteger();

		private FinalManifestCommitMapFullValueStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config);
		}

		private static void resetFailure() {
			failAfterDrop.set(true);
			sawSuccessfulDrop.set(false);
			injectedMapFull.set(false);
			environmentCloseCount.set(0);
		}

		@Override
		int dropTermIndexDatabase(long transaction, int dbi) {
			int rc = super.dropTermIndexDatabase(transaction, dbi);
			if (rc == MDB_SUCCESS) {
				sawSuccessfulDrop.set(true);
			}
			return rc;
		}

		@Override
		int commitWriteTransaction(long transaction) {
			if (sawSuccessfulDrop.get() && failAfterDrop.compareAndSet(true, false)) {
				mdb_txn_abort(transaction);
				injectedMapFull.set(true);
				return MDB_MAP_FULL;
			}
			return super.commitWriteTransaction(transaction);
		}

		@Override
		void closeEnvironment(long environment) {
			environmentCloseCount.incrementAndGet();
			super.closeEnvironment(environment);
		}
	}

	private static final class DropMapFullValueStore extends ValueStore {

		private static boolean injectMapFullAfterNextSuccessfulDrop;

		private DropMapFullValueStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config);
		}

		@Override
		int dropTermIndexDatabase(long transaction, int dbi) {
			int rc = super.dropTermIndexDatabase(transaction, dbi);
			if (rc == 0 && injectMapFullAfterNextSuccessfulDrop) {
				injectMapFullAfterNextSuccessfulDrop = false;
				return MDB_MAP_FULL;
			}
			return rc;
		}
	}

